const GOLDEN: &str = include_str!("../fixtures/gguf/blocks.json");
const MOE: &str = include_str!("../fixtures/qwen3_5_moe_config.json");
/// Two recurrent and two attention layers, every width a multiple of 256.
const SMALL: &str = r#"{
  "architectures": ["Qwen3_5ForCausalLM"], "model_type": "qwen3_5_text",
  "hidden_size": 256, "intermediate_size": 512, "vocab_size": 160, "num_hidden_layers": 4,
  "num_attention_heads": 4, "num_key_value_heads": 2, "head_dim": 64,
  "linear_num_key_heads": 2, "linear_num_value_heads": 4, "linear_key_head_dim": 64,
  "linear_value_head_dim": 64, "linear_conv_kernel_dim": 4, "max_position_embeddings": 4096,
  "rms_norm_eps": 1e-6, "hidden_act": "silu", "attention_bias": false, "attn_output_gate": true,
  "tie_word_embeddings": false, "eos_token_id": 1,
  "layer_types": ["linear_attention", "full_attention", "linear_attention", "full_attention"],
  "rope_parameters": {"rope_type": "default", "rope_theta": 10000000.0, "partial_rotary_factor": 0.25}
}"#;

fn hex(text: &str) -> Vec<u8> {
    text.as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| {
            let digit = |c: u8| (c as char).to_digit(16).unwrap_or(0) as u8;
            digit(pair[0]) * 16 + digit(pair[1])
        })
        .collect()
}

/// A format, blocks in it, and the values ggml decoded them to.
type Golden = (BlockFormat, Vec<u8>, Vec<f32>);

/// Every packed format's golden blocks.
fn golden() -> Result<Vec<Golden>> {
    let golden: serde_json::Value = serde_json::from_str(GOLDEN)?;
    Ok(BlockFormat::ALL
        .into_iter()
        .filter(|format| format.block_values() > 1)
        .map(|format| {
            let entry = &golden[format.name()];
            let values = entry["values"]
                .as_array()
                .into_iter()
                .flatten()
                .map(|value| {
                    let bytes = hex(value.as_str().unwrap_or_default());
                    f32::from_le_bytes([bytes[0], bytes[1], bytes[2], bytes[3]])
                })
                .collect();
            (
                format,
                hex(entry["blocks"].as_str().unwrap_or_default()),
                values,
            )
        })
        .collect())
}

fn assert_close(actual: &[f32], expected: &[f32], tolerance: f32, label: &str) {
    assert_eq!(actual.len(), expected.len(), "{label}");
    let scale = expected.iter().fold(1e-3f32, |m, v| m.max(v.abs()));
    for (i, (a, b)) in actual.iter().zip(expected).enumerate() {
        assert!(
            (a - b).abs() <= tolerance * scale,
            "{label} value {i}: {a} against {b}"
        );
    }
}

fn activations(rows: usize, cols: usize) -> Vec<f32> {
    (0..rows * cols)
        .map(|i| ((i * 2_654_435_761 % 1009) as f32 - 504.0) / 512.0)
        .collect()
}

/// `x · Wᵀ` in F64, so the reference's rounding cannot excuse a kernel's error.
fn reference(x: &[f32], rows: usize, weights: &[f32], cols: usize) -> Vec<f32> {
    let n = weights.len() / cols;
    let mut out = vec![0.0; rows * n];
    for r in 0..rows {
        for o in 0..n {
            let row = &weights[o * cols..(o + 1) * cols];
            let xr = &x[r * cols..(r + 1) * cols];
            let dot: f64 = row
                .iter()
                .zip(xr)
                .map(|(w, v)| f64::from(*w) * f64::from(*v))
                .sum();
            out[r * n + o] = dot as f32;
        }
    }
    out
}

fn read(tensor: &Tensor) -> Result<Vec<f32>> {
    Ok(tensor.to_device(&Device::Cpu)?.flatten_all()?.to_vec1()?)
}

#[test]
fn test_host_decoder_matches_ggml_in_every_format() -> Result<()> {
    let formats = golden()?;
    assert_eq!(formats.len(), 20);
    for (format, blocks, expected) in formats {
        let decoded = format.decode(&blocks, 512)?;
        assert_eq!(decoded.len(), 512, "{}", format.name());
        for (i, (a, b)) in decoded.iter().zip(&expected).enumerate() {
            assert!(
                (a - b).abs() <= 1e-6 * b.abs().max(1e-6),
                "{} value {i}: {a} against ggml's {b}",
                format.name()
            );
        }
    }
    Ok(())
}

#[test]
fn test_block_kernels_match_ggml_in_every_format_and_batch_size() -> Result<()> {
    let device = Device::new_metal(0)?;
    let kernels = Kernels::new(&device)?;
    let cols = 256;
    for (format, blocks, values) in golden()? {
        // The golden tensor has 512 values: two rows of 256.
        let bytes = blocks.clone();
        let layer = PackedLinear::from_parts(
            vec![StoredPart {
                format,
                rows: 2,
                bytes,
            }],
            cols,
            &device,
        )?;
        assert_eq!(layer.resident_bytes(), blocks.len(), "{}", format.name());
        for rows in [1, 2, 3, 8, 9, 16, 17, 40] {
            let x = activations(rows, cols);
            let input = Tensor::from_slice(&x, (rows, cols), &device)?;
            let label = format!("{} at {rows} rows", format.name());
            let actual = read(&kernels.linear(&layer, &input)?)?;
            let expected = reference(&x, rows, &values, cols);
            // Wide batches round weights through F16, on Candle's tiles and the block kernels.
            let rounded = rows > 8;
            assert_close(
                &actual,
                &expected,
                if rounded { 2e-3 } else { 2e-5 },
                &label,
            );
        }
    }
    Ok(())
}

#[test]
fn test_mixed_parts_keep_their_bytes_and_fill_their_own_outputs() -> Result<()> {
    let device = Device::new_metal(0)?;
    let kernels = Kernels::new(&device)?;
    let cols = 256;
    let all = golden()?;
    let mut parts = Vec::new();
    let mut values = Vec::new();
    let mut bytes = 0;
    for (format, blocks, decoded) in all.iter().rev() {
        parts.push(StoredPart {
            format: *format,
            rows: 2,
            bytes: blocks.clone(),
        });
        values.extend_from_slice(decoded);
        bytes += blocks.len();
    }
    let layer = PackedLinear::from_parts(parts, cols, &device)?;
    assert_eq!(layer.out_features(), 2 * all.len());
    assert_eq!(layer.resident_bytes(), bytes);
    for rows in [1, 2, 3, 4, 5, 8, 9, 16, 17, 33, 70] {
        let x = activations(rows, cols);
        let input = Tensor::from_slice(&x, (rows, cols), &device)?;
        assert_close(
            &read(&kernels.linear(&layer, &input)?)?,
            &reference(&x, rows, &values, cols),
            if rows > 8 { 2e-3 } else { 2e-5 },
            &format!("mixed parts at {rows} rows"),
        );
    }
    Ok(())
}

#[test]
fn test_parts_that_do_not_form_their_shape_are_rejected() -> Result<()> {
    let part = |rows, bytes: usize| StoredPart {
        format: BlockFormat::Q3K,
        rows,
        bytes: vec![0; bytes],
    };
    let device = Device::new_metal(0)?;
    assert!(PackedLinear::from_parts(vec![part(2, 110)], 256, &device).is_err());
    assert!(PackedLinear::from_parts(vec![part(1, 110)], 300, &device).is_err());
    assert!(PackedLinear::from_parts(Vec::new(), 256, &device).is_err());
    Ok(())
}

/// One tensor of a GGUF fixture: name, ggml dimensions, ggml type and payload.
type Written = (String, Vec<u64>, u32, Vec<u8>);

fn gguf_string(out: &mut Vec<u8>, text: &str) {
    out.extend_from_slice(&(text.len() as u64).to_le_bytes());
    out.extend_from_slice(text.as_bytes());
}

/// A metadata value a fixture writes beside `general.architecture`.
enum Meta {
    Text(String),
    U32(u32),
    Strings(Vec<String>),
}

fn write_gguf(
    path: &Path,
    architecture: &str,
    metadata: &[(&str, Meta)],
    tensors: &[Written],
) -> Result<()> {
    let mut out = b"GGUF".to_vec();
    out.extend_from_slice(&3u32.to_le_bytes());
    out.extend_from_slice(&(tensors.len() as u64).to_le_bytes());
    out.extend_from_slice(&(1 + metadata.len() as u64).to_le_bytes());
    gguf_string(&mut out, "general.architecture");
    out.extend_from_slice(&8u32.to_le_bytes());
    gguf_string(&mut out, architecture);
    for (key, value) in metadata {
        gguf_string(&mut out, key);
        match value {
            Meta::Text(text) => {
                out.extend_from_slice(&8u32.to_le_bytes());
                gguf_string(&mut out, text);
            }
            Meta::U32(number) => {
                out.extend_from_slice(&4u32.to_le_bytes());
                out.extend_from_slice(&number.to_le_bytes());
            }
            Meta::Strings(strings) => {
                out.extend_from_slice(&9u32.to_le_bytes());
                out.extend_from_slice(&8u32.to_le_bytes());
                out.extend_from_slice(&(strings.len() as u64).to_le_bytes());
                for text in strings {
                    gguf_string(&mut out, text);
                }
            }
        }
    }
    let mut offset = 0u64;
    for (name, dims, ggml_type, bytes) in tensors {
        gguf_string(&mut out, name);
        out.extend_from_slice(&(dims.len() as u32).to_le_bytes());
        for dim in dims {
            out.extend_from_slice(&dim.to_le_bytes());
        }
        out.extend_from_slice(&ggml_type.to_le_bytes());
        out.extend_from_slice(&offset.to_le_bytes());
        offset = (offset + bytes.len() as u64).next_multiple_of(32);
    }
    out.resize(out.len().next_multiple_of(32), 0);
    for (_, _, _, bytes) in tensors {
        out.extend_from_slice(bytes);
        out.resize(out.len().next_multiple_of(32), 0);
    }
    Ok(std::fs::write(path, out)?)
}

/// Formats the fixture cycles through: every matrix format Candle can also produce.
const CYCLE: [(GgmlDType, BlockFormat, u32); 8] = [
    (GgmlDType::Q3K, BlockFormat::Q3K, 11),
    (GgmlDType::Q5K, BlockFormat::Q5K, 13),
    (GgmlDType::Q2K, BlockFormat::Q2K, 10),
    (GgmlDType::Q6K, BlockFormat::Q6K, 14),
    (GgmlDType::Q4K, BlockFormat::Q4K, 12),
    (GgmlDType::Q8_0, BlockFormat::Q8_0, 8),
    (GgmlDType::Q5_0, BlockFormat::Q5_0, 6),
    (GgmlDType::Q4_1, BlockFormat::Q4_1, 3),
];

/// GGUF names of every tensor llama.cpp writes for these layers, across model families.
fn gguf_names(layers: usize) -> Vec<String> {
    let mut names: Vec<String> = [
        "token_embd.weight",
        "output.weight",
        "output_norm.weight",
        "per_layer_token_embd.weight",
        "per_layer_model_proj.weight",
        "per_layer_proj_norm.weight",
    ]
    .map(str::to_owned)
    .to_vec();
    for layer in 0..layers {
        for tensor in [
            "attn_norm.weight",
            "post_attention_norm.weight",
            "ffn_norm.weight",
            "post_ffw_norm.weight",
            "post_norm.weight",
            "layer_output_scale.weight",
            "inp_gate.weight",
            "proj.weight",
            "attn_q.weight",
            "attn_k.weight",
            "attn_v.weight",
            "attn_output.weight",
            "attn_q_norm.weight",
            "attn_k_norm.weight",
            "attn_qkv.weight",
            "attn_gate.weight",
            "ssm_beta.weight",
            "ssm_alpha.weight",
            "ssm_out.weight",
            "ssm_conv1d.weight",
            "ssm_norm.weight",
            "ssm_dt.bias",
            "ssm_a",
            "ffn_gate.weight",
            "ffn_up.weight",
            "ffn_down.weight",
            "ffn_gate_inp.weight",
            "ffn_gate_exps.weight",
            "ffn_up_exps.weight",
            "ffn_down_exps.weight",
            "ffn_gate_inp_shexp.weight",
            "ffn_gate_shexp.weight",
            "ffn_up_shexp.weight",
            "ffn_down_shexp.weight",
        ] {
            names.push(format!("blk.{layer}.{tensor}"));
        }
    }
    names
}

/// A GGUF of `source`'s tensors, written as llama.cpp's converter does with formats cycling
/// per tensor, beside a `SafeTensors` copy holding exactly what those blocks decode to.
fn convert(
    source: &Path,
    config: &impl WeightLayout,
    cycle: usize,
    shared_banks: bool,
) -> Result<(Checkpoint, PathBuf, Checkpoint)> {
    let tensors = candle_core::safetensors::load(source.join("model.safetensors"), &Device::Cpu)?;
    let heads = linear_heads(source)?;
    let shapes = config.stored_shapes()?;
    let mut decoded: HashMap<String, Tensor> = HashMap::new();
    let mut written: Vec<Written> = Vec::new();
    let read = |name: &str| -> Result<Vec<f32>> {
        Ok(tensors[name]
            .to_dtype(DType::F32)?
            .flatten_all()?
            .to_vec1::<f32>()?)
    };
    let mut index = cycle;
    for gguf in gguf_names(8) {
        let Some(GgufTensor::Stored { name, adjust }) = config.gguf_tensor(&gguf) else {
            continue;
        };
        let part = name
            .strip_suffix(".gate_proj")
            .or_else(|| name.strip_suffix(".up_proj"))
            .filter(|_| name.contains(".experts."));
        let source_name =
            part.map_or_else(|| name.clone(), |prefix| format!("{prefix}.gate_up_proj"));
        if !shapes.contains_key(&source_name) {
            continue;
        }
        let shape = &shapes[&source_name];
        let mut values = read(&source_name)?;
        let mut shape = shape.clone();
        // The file holds llama.cpp's tiled value-head order; `decoded` keeps the checkpoint's.
        let order = heads.and_then(|heads| tiled_order(&name, &shape, heads));
        let grouped = |tiled: Vec<f32>| -> Vec<f32> {
            let Some(order) = &order else { return tiled };
            let mut out = vec![0.0; tiled.len()];
            for (value, &at) in tiled.into_iter().zip(order) {
                out[at] = value;
            }
            out
        };
        let original = values.clone();
        if let Some(order) = &order {
            values = order.iter().map(|&at| original[at]).collect();
        }
        if part.is_some() {
            // Each expert's gate rows, then its up rows.
            let (experts, rows, cols) = (shape[0], shape[1] / 2, shape[2]);
            let up = name.ends_with(".up_proj");
            values = (0..experts)
                .flat_map(|e| {
                    let start = (e * 2 * rows + usize::from(up) * rows) * cols;
                    values[start..start + rows * cols].to_vec()
                })
                .collect();
            shape = vec![experts, rows, cols];
        }
        let cols = *shape.last().unwrap_or(&1);
        let matrix = shape.len() >= 2 && cols.is_multiple_of(256) && !name.contains("conv1d");
        let (ggml_type, bytes, stored) = if matrix && !name.contains(".gate.weight") {
            let (candle, format, ggml_type) = CYCLE[index % CYCLE.len()];
            // A bank's gate tensor shares its format with the up tensor written next, so the
            // bank stays as stored.
            index += usize::from(!shared_banks || !name.ends_with(".experts.gate_proj"));
            let bytes = quantize(&values, cols, candle, None)?;
            let stored = grouped(format.decode(&bytes, cols)?);
            (ggml_type, bytes, stored)
        } else {
            let stored = match adjust {
                Adjust::None => values.clone(),
                Adjust::Uncenter => values.iter().map(|v| v + 1.0).collect(),
                Adjust::LogNegated => values.iter().map(|v| -v.exp()).collect(),
            };
            let bytes = stored.iter().flat_map(|v| v.to_le_bytes()).collect();
            (0, bytes, original)
        };
        // ggml orders dimensions innermost first and drops the convolution's unit one.
        let mut dims: Vec<u64> = shape.iter().rev().map(|&d| d as u64).collect();
        if name.contains("conv1d") {
            dims.retain(|&d| d != 1);
        }
        written.push((gguf, dims, ggml_type, bytes));
        decoded.insert(name, Tensor::from_vec(stored, shape, &Device::Cpu)?);
    }
    // Restack the banks the F32 copy loads as one tensor.
    let banks: Vec<String> = decoded
        .keys()
        .filter_map(|name| name.strip_suffix(".gate_proj"))
        .filter(|prefix| prefix.ends_with(".experts"))
        .map(str::to_owned)
        .collect();
    for prefix in banks {
        let gate = decoded
            .remove(&format!("{prefix}.gate_proj"))
            .ok_or_else(|| invalid("bank has no gate"))?;
        let up = decoded
            .remove(&format!("{prefix}.up_proj"))
            .ok_or_else(|| invalid("bank has no up"))?;
        decoded.insert(
            format!("{prefix}.gate_up_proj"),
            Tensor::cat(&[gate, up], 1)?,
        );
    }
    let temp = |label: &str| -> Result<Checkpoint> {
        let dir = std::env::temp_dir().join(format!("tur-gguf-{label}-{}", uuid::Uuid::new_v4()));
        std::fs::create_dir_all(&dir)?;
        Ok(Checkpoint(dir))
    };
    let holder = temp("file")?;
    let path = holder.0.join(format!("weights-{cycle}.gguf"));
    write_gguf(&path, config.gguf_architectures()[0], &[], &written)?;
    let copy = temp("decoded")?;
    std::fs::copy(source.join("config.json"), copy.0.join("config.json"))?;
    candle_core::safetensors::save(&decoded, copy.0.join("model.safetensors"))?;
    Ok((holder, path, copy))
}

fn options(weights: Weights, device: &Device) -> LoadOptions {
    LoadOptions {
        revision: "gguf-fixture".into(),
        weights,
        device: device.clone(),
        execution: Execution::Fused,
        kv: KvLayout::new(16, KvFormat::F32),
        recurrent: DType::F32,
        mtp: None,
        audio: false,
        vision: false,
        video: false,
        expert_cache: None,
    }
}

/// Logits of the same tokens through a Qwen model, in chunks.
fn logits(model: &Qwen35, vocab: u32) -> Result<Vec<Vec<f32>>> {
    let tokens: Vec<u32> = (0..24).map(|i| (i * 37 + 11) % (vocab - 2) + 2).collect();
    let pool = pool(model, 32, 2)?;
    let (out, _) = prefill(model, ModelState::new(&pool), &tokens, 16)?;
    Ok(out)
}

#[test]
fn test_gguf_models_compute_what_their_blocks_decode_to() -> Result<()> {
    let device = Device::new_metal(0)?;
    let tied = SMALL.replace(
        "\"tie_word_embeddings\": false",
        "\"tie_word_embeddings\": true",
    );
    for config_json in [SMALL, tied.as_str(), MOE] {
        let config = Config::from_json(config_json)?;
        let vocab = config.vocab_size() as u32;
        let source = checkpoint(config_json, 0.08, 0.1)?;
        for cycle in [0, 3] {
            let (_holder, path, decoded) = convert(&source.0, &config, cycle, true)?;
            let weights = Weights::Gguf(Arc::new(GgufFile::open(&path)?));
            let options = options(weights, &device);
            let (_, planned, _) = Qwen35::memory_requirements(&config, &options, 64, &[64])?;
            let model = Qwen35::load(&source.0, &options)?;
            assert_eq!(planned, model.weight_bytes());
            let reference = Qwen35::load(
                &decoded.0,
                &self::options(Weights::Uniform(WeightFormat::F32), &device),
            )?;
            let expected = logits(&reference, vocab)?;
            let error = max_relative(&logits(&model, vocab)?, &expected);
            // Prefill chunks of 16 round weights through F16 on Candle's tiles.
            assert!(error < 2e-3, "cycle {cycle}: relative error {error}");
            // The reference operations read the file's value-head order too. Their batched
            // GEMM stages weight tiles as F16, which `test_fused_packed_formats_track_reference`
            // bounds the same way; the checkpoint's grouped order would be off by about 0.5.
            let composed = Qwen35::load(
                &source.0,
                &LoadOptions {
                    execution: Execution::Reference,
                    ..self::options(Weights::Gguf(Arc::new(GgufFile::open(&path)?)), &device)
                },
            )?;
            let error = max_relative(&logits(&composed, vocab)?, &expected);
            assert!(
                error < 2e-2,
                "cycle {cycle}: reference relative error {error}"
            );
        }
    }
    Ok(())
}

#[test]
fn test_expert_banks_mixing_formats_are_packed_again_within_their_plan() -> Result<()> {
    let device = Device::new_metal(0)?;
    let config = Config::from_json(MOE)?;
    let source = checkpoint(MOE, 0.08, 0.1)?;
    let (_holder, path, _decoded) = convert(&source.0, &config, 0, false)?;
    let weights = Weights::Gguf(Arc::new(GgufFile::open(&path)?));
    let options = options(weights, &device);
    let (_, planned, _) = Qwen35::memory_requirements(&config, &options, 64, &[64])?;
    let model = Qwen35::load(&source.0, &options)?;
    assert_eq!(planned, model.weight_bytes());
    let output = logits(&model, config.vocab_size() as u32)?;
    assert!(output.iter().flatten().all(|value| value.is_finite()));
    Ok(())
}

/// Reformat a file's expert banks to mix formats across layers as real files do, with a block
/// format Candle cannot read in the last layer, and return each layer's bytes per expert.
fn mix_bank_formats(tensors: &mut [Written], experts: usize) -> Result<Vec<usize>> {
    let mut per_expert = Vec::new();
    for (name, dims, ggml_type, bytes) in tensors {
        let Some(layer) = name
            .strip_prefix("blk.")
            .filter(|_| name.ends_with("_exps.weight"))
            .and_then(|rest| rest.split('.').next())
            .and_then(|layer| layer.parse::<usize>().ok())
        else {
            continue;
        };
        let cols = dims[0] as usize;
        let rows = (dims[1] * dims[2]) as usize;
        let format = BlockFormat::from_ggml(*ggml_type).ok_or_else(|| invalid("bank format"))?;
        let values = format.decode(&bytes[..format.bytes(rows, cols)?], cols)?;
        (*ggml_type, *bytes) = if layer == 3 {
            // BF16 is the upper half of F32.
            let halves = values
                .iter()
                .flat_map(|v| ((v.to_bits() >> 16) as u16).to_le_bytes());
            (30, halves.collect())
        } else if name.contains("ffn_down") {
            (13, quantize(&values, cols, GgmlDType::Q5K, None)?)
        } else {
            (12, quantize(&values, cols, GgmlDType::Q4K, None)?)
        };
        per_expert.resize(per_expert.len().max(layer + 1), 0);
        per_expert[layer] += bytes.len() / experts;
    }
    Ok(per_expert)
}

/// Experts behind a cache read a GGUF file's blocks as stored: with formats mixed across
/// layers, gate and up rows in separate shards, and eviction between and within passes, every
/// logit is bit-identical to keeping all of them resident.
#[test]
fn test_expert_cache_over_gguf_files_is_bit_identical_to_resident() -> Result<()> {
    let device = Device::new_metal(0)?;
    let experts = 8;
    let json = MOE
        .replace("\"num_hidden_layers\": 2", "\"num_hidden_layers\": 4")
        .replace(
            "[\"linear_attention\", \"full_attention\"]",
            "[\"linear_attention\", \"full_attention\", \"linear_attention\", \"full_attention\"]",
        );
    let config = Config::from_json(&json)?;
    let vocab = config.vocab_size() as u32;
    let source = checkpoint(&json, 0.03, 0.1)?;
    let (holder, path, _decoded) = convert(&source.0, &config, 0, true)?;
    let mut tensors = read_written(&path)?;
    let per_expert = mix_bank_formats(&mut tensors, experts)?;
    let split = tensors
        .iter()
        .position(|tensor| tensor.0 == "blk.1.ffn_up_exps.weight")
        .ok_or_else(|| invalid("fixture has no second layer's up bank"))?;
    let shard = |index: usize| holder.0.join(format!("mixed-{index:05}-of-00002.gguf"));
    let architecture = config.gguf_architectures()[0];
    write_gguf(&shard(1), architecture, &[], &tensors[..split])?;
    write_gguf(&shard(2), architecture, &[], &tensors[split..])?;
    let weights = Weights::Gguf(Arc::new(GgufFile::open(&shard(1))?));
    let load = |expert_cache| LoadOptions {
        expert_cache,
        ..options(weights.clone(), &device)
    };
    let resident = Qwen35::load(&source.0, &load(None))?;
    let expected = logits(&resident, vocab)?;
    // One format class for the first three layers and one for the last.
    let floor = experts * (per_expert[0] + per_expert[3]);
    assert!(Qwen35::memory_requirements(&config, &load(Some(floor - 1)), 64, &[64]).is_err());
    let cached = load(Some(floor + 3 * per_expert[0]));
    let model = Qwen35::load(&source.0, &cached)?;
    for pass in 0..2 {
        let actual = logits(&model, vocab)?;
        for (a, e) in actual.iter().flatten().zip(expected.iter().flatten()) {
            assert_eq!(a.to_bits(), e.to_bits(), "pass {pass}");
        }
    }
    let stats = model
        .expert_stats()
        .ok_or_else(|| invalid("missing expert stats"))?;
    assert!(stats.misses > 0 && stats.evictions > 0, "{stats:?}");
    let (_, planned, _) = Qwen35::memory_requirements(&config, &cached, 64, &[64])?;
    assert_eq!(planned, model.weight_bytes());
    assert!(model.weight_bytes() < resident.weight_bytes());
    Ok(())
}

/// A bank whose gate and up rows differ would have to be packed again on every read.
#[test]
fn test_expert_cache_rejects_banks_whose_gate_and_up_differ() -> Result<()> {
    let device = Device::new_metal(0)?;
    let config = Config::from_json(MOE)?;
    let source = checkpoint(MOE, 0.08, 0.1)?;
    let (_holder, path, _decoded) = convert(&source.0, &config, 0, false)?;
    let options = LoadOptions {
        expert_cache: Some(1 << 24),
        ..options(Weights::Gguf(Arc::new(GgufFile::open(&path)?)), &device)
    };
    let error = Qwen35::memory_requirements(&config, &options, 64, &[64])
        .err()
        .ok_or_else(|| invalid("mixed gate and up were accepted"))?;
    assert!(error.to_string().contains("different formats"), "{error}");
    Ok(())
}

#[test]
fn test_gemma_gguf_with_shared_keys_and_per_layer_inputs_matches_decoded_weights() -> Result<()> {
    let device = Device::new_metal(0)?;
    let source = Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/gemma4/dense");
    let config = GemmaConfig::from_json(&std::fs::read_to_string(source.join("config.json"))?)?;
    let (_holder, path, decoded) = convert(&source, &config, 0, true)?;
    let weights = Weights::Gguf(Arc::new(GgufFile::open(&path)?));
    let options = options(weights, &device);
    let (_, planned, _) = Gemma4::memory_requirements(&config, &options, 9, &[9])?;
    let model = Gemma4::load(&source, &options)?;
    assert_eq!(planned, model.weight_bytes());
    let reference = Gemma4::load(
        &decoded.0,
        &self::options(Weights::Uniform(WeightFormat::F32), &device),
    )?;
    let tokens: Vec<u32> = (0..9).map(|i| i * 3 + 2).collect();
    let run = |model: &Gemma4| -> Result<Vec<Vec<f32>>> {
        let pool = StatePool::new(
            Arc::new(model.description()),
            model.device(),
            PoolConfig {
                pages: 256,
                window_pages: 256,
                recurrent_slots: 1,
                index_blocks: 0,
            },
        )?;
        Ok(prefill(model, ModelState::new(&pool), &tokens, 4)?.0)
    };
    let error = max_relative(&run(&model)?, &run(&reference)?);
    assert!(error < 1e-4, "relative error {error}");
    Ok(())
}

#[test]
fn test_gguf_files_that_do_not_fit_the_model_fail_before_loading() -> Result<()> {
    let config = Config::from_json(SMALL)?;
    let source = checkpoint(SMALL, 0.08, 0.1)?;
    let (_holder, path, _decoded) = convert(&source.0, &config, 0, true)?;
    let bytes = std::fs::read(&path)?;
    let message = |file: Result<GgufFile>| match file
        .and_then(|file| Weights::Gguf(Arc::new(file)).plan(&config))
    {
        Ok(_) => String::new(),
        Err(error) => error.to_string(),
    };
    // A file cut short.
    let short = path.with_extension("short");
    std::fs::write(&short, &bytes[..bytes.len() / 2])?;
    assert!(message(GgufFile::open(&short)).contains("past its file"));
    // Not GGUF at all.
    let junk = path.with_extension("junk");
    std::fs::write(&junk, b"not a gguf file")?;
    assert!(message(GgufFile::open(&junk)).contains("not a GGUF file"));
    // Another architecture, a missing tensor, a wrong shape and an unreadable type.
    let tensor = |name: &str, dims: Vec<u64>, ggml_type, bytes: usize| -> Written {
        (name.to_owned(), dims, ggml_type, vec![0; bytes])
    };
    let other = path.with_extension("other");
    write_gguf(
        &other,
        "llama",
        &[],
        &[tensor(
            "token_embd.weight",
            vec![256, 160],
            0,
            256 * 160 * 4,
        )],
    )?;
    assert!(message(GgufFile::open(&other)).contains("does not match"));
    write_gguf(
        &other,
        "qwen35",
        &[],
        &[tensor(
            "token_embd.weight",
            vec![256, 160],
            0,
            256 * 160 * 4,
        )],
    )?;
    assert!(message(GgufFile::open(&other)).contains("no tensor for"));
    write_gguf(
        &other,
        "qwen35",
        &[],
        &[tensor("token_embd.weight", vec![512, 80], 0, 512 * 80 * 4)],
    )?;
    assert!(message(GgufFile::open(&other)).contains("expected"));
    write_gguf(
        &other,
        "qwen35",
        &[],
        &[tensor(
            "token_embd.weight",
            vec![256, 160],
            34,
            256 * 160 * 4,
        )],
    )?;
    assert!(message(GgufFile::open(&other)).contains("cannot read"));
    write_gguf(
        &other,
        "qwen35",
        &[],
        &[tensor("blk.0.unknown", vec![4], 0, 16)],
    )?;
    assert!(message(GgufFile::open(&other)).contains("no place"));
    Ok(())
}

#[test]
fn test_split_files_load_from_their_first_shard_and_need_every_shard() -> Result<()> {
    let config = Config::from_json(SMALL)?;
    let source = checkpoint(SMALL, 0.08, 0.1)?;
    let (holder, path, _decoded) = convert(&source.0, &config, 0, true)?;
    let whole = Weights::Gguf(Arc::new(GgufFile::open(&path)?)).plan(&config)?;
    // Rewrite the fixture's tensors into two shards through a fresh conversion of one file.
    let tensors = read_written(&path)?;
    let (first, second) = tensors.split_at(tensors.len() / 2);
    let shard = |index: usize| holder.0.join(format!("model-{index:05}-of-00002.gguf"));
    write_gguf(&shard(1), "qwen35", &[], first)?;
    assert!(
        GgufFile::open(&shard(1)).is_err(),
        "a missing shard must fail"
    );
    write_gguf(&shard(2), "qwen35", &[], second)?;
    let split = Weights::Gguf(Arc::new(GgufFile::open(&shard(1))?)).plan(&config)?;
    assert_eq!(split, whole);
    Ok(())
}

#[test]
fn test_gguf_files_bring_their_template_and_must_match_the_tokenizer() -> Result<()> {
    use tur_models::backend::chat_template::{ChatMessage, RenderOptions, Role};
    use tur_models::backend::factory::GgufSource;
    let source = Checkpoint::fused()?;
    let config = Config::from_json(&std::fs::read_to_string(source.0.join("config.json"))?)?;
    let (holder, path, _decoded) = convert(&source.0, &config, 0, true)?;
    let tensors = read_written(&path)?;
    // The fixture's tokenizer spells IDs as `t<id>`, and llama.cpp pads the rest of the vocabulary.
    let tokens = |changed: Option<usize>| -> Vec<String> {
        (0..config.vocab_size())
            .map(|id| match changed {
                Some(at) if at == id => "edited".to_owned(),
                _ => format!("t{id}"),
            })
            .collect()
    };
    let device = Device::new_metal(0)?;
    let factory = |file: &Path| tur::ModelFactory {
        format: None,
        device: device.clone(),
        gguf: Some(GgufSource::LocalPath(file.to_path_buf())),
        ..source.factory()
    };
    let render = |messages: &[ChatMessage]| -> Result<String> {
        let (_, _, template, _) = factory(&path).create_model()?;
        template.render(messages, &[], &RenderOptions::default())
    };
    let hello = [ChatMessage::new(Role::User, "hello")];
    assert_eq!(
        render(&hello)?,
        "hello ",
        "no template in the file: the checkpoint's"
    );
    let file = holder.0.join("with-metadata.gguf");
    let architecture = config.gguf_architectures()[0];
    write_gguf(
        &file,
        architecture,
        &[
            (
                "tokenizer.chat_template",
                Meta::Text("file:{% for m in messages %}{{ m.content }}{% endfor %}".into()),
            ),
            ("tokenizer.ggml.tokens", Meta::Strings(tokens(None))),
            ("tokenizer.ggml.eos_token_id", Meta::U32(7)),
        ],
        &tensors,
    )?;
    let (_, _, template, defaults) = factory(&file).create_model()?;
    assert_eq!(
        template.render(&hello, &[], &RenderOptions::default())?,
        "file:hello"
    );
    assert!(
        defaults.eos_tokens.contains(&7),
        "{:?}",
        defaults.eos_tokens
    );
    write_gguf(
        &file,
        architecture,
        &[("tokenizer.ggml.tokens", Meta::Strings(tokens(Some(5))))],
        &tensors,
    )?;
    let error = factory(&file).create_model().err().map(|e| e.to_string());
    assert!(
        error.as_deref().is_some_and(|e| e.contains("GGUF token 5")),
        "{error:?}"
    );
    Ok(())
}

/// Key heads, value heads, key dim and value dim of a checkpoint whose linear attention
/// has more value heads than key heads: the case llama.cpp's converter reorders.
fn linear_heads(source: &Path) -> Result<Option<[usize; 4]>> {
    let config: serde_json::Value =
        serde_json::from_str(&std::fs::read_to_string(source.join("config.json"))?)?;
    let field = |name: &str| config[name].as_u64().map(|value| value as usize);
    Ok(
        match [
            "linear_num_key_heads",
            "linear_num_value_heads",
            "linear_key_head_dim",
            "linear_value_head_dim",
        ]
        .map(field)
        {
            [Some(k), Some(v), Some(dk), Some(dv)] if k != v => Some([k, v, dk, dv]),
            _ => None,
        },
    )
}

/// For a linear-attention tensor llama.cpp's converter reorders, the checkpoint element each
/// element of the file holds: value heads move from grouped by key head
/// (`[k0v0, k0v1, k1v0, k1v1]`) to tiled (`[k0v0, k1v0, k0v1, k1v1]`).
fn tiled_order(name: &str, shape: &[usize], [k, v, dk, dv]: [usize; 4]) -> Option<Vec<usize>> {
    let tensor = name.split(".linear_attn.").nth(1)?;
    let key_width = k * dk;
    // (first reordered row, values per head) along the rows, or along the columns.
    let (start, head, columns) = match tensor {
        "in_proj_qkv.weight" | "conv1d.weight" => (2 * key_width, dv, false),
        "in_proj_z.weight" => (0, dv, false),
        "in_proj_a.weight" | "in_proj_b.weight" | "A_log" | "dt_bias" => (0, 1, false),
        "out_proj.weight" => (0, dv, true),
        _ => return None,
    };
    let per_key = v / k;
    // Tiled position `j` of the reordered span holds grouped position `heads[j]`.
    let heads: Vec<usize> = (0..per_key)
        .flat_map(|r| {
            (0..k).flat_map(move |g| (0..head).map(move |d| (g * per_key + r) * head + d))
        })
        .collect();
    let rows = shape[0];
    let width: usize = shape[1..].iter().product();
    Some(
        (0..rows * width)
            .map(|at| {
                let (row, col) = (at / width, at % width);
                if columns {
                    row * width + heads[col]
                } else if row >= start {
                    (start + heads[row - start]) * width + col
                } else {
                    at
                }
            })
            .collect(),
    )
}

/// The tensors of a file `write_gguf` wrote, with their payloads.
fn read_written(path: &Path) -> Result<Vec<Written>> {
    let bytes = std::fs::read(path)?;
    let u64_at =
        |at: usize| -> u64 { u64::from_le_bytes(bytes[at..at + 8].try_into().unwrap_or_default()) };
    let u32_at =
        |at: usize| -> u32 { u32::from_le_bytes(bytes[at..at + 4].try_into().unwrap_or_default()) };
    let count = u64_at(8) as usize;
    // The one metadata pair: key, value type, value.
    let mut at = 24;
    at += 8 + u64_at(at) as usize + 4;
    at += 8 + u64_at(at) as usize;
    let mut table = Vec::with_capacity(count);
    for _ in 0..count {
        let length = u64_at(at) as usize;
        let name = String::from_utf8_lossy(&bytes[at + 8..at + 8 + length]).into_owned();
        at += 8 + length;
        let rank = u32_at(at) as usize;
        at += 4;
        let dims: Vec<u64> = (0..rank).map(|i| u64_at(at + 8 * i)).collect();
        at += 8 * rank;
        table.push((name, dims, u32_at(at), u64_at(at + 4) as usize));
        at += 12;
    }
    let start = at.next_multiple_of(32);
    let mut tensors = Vec::with_capacity(count);
    for (index, (name, dims, ggml_type, offset)) in table.iter().enumerate() {
        let end = table
            .get(index + 1)
            .map_or(bytes.len() - start, |next| next.3);
        tensors.push((
            name.clone(),
            dims.clone(),
            *ggml_type,
            bytes[start + offset..start + end].to_vec(),
        ));
    }
    Ok(tensors)
}
